using Text=std::array<const char*,6>;
static QString T(const Text &text){
    size_t language=LanguageIndex();QString value=QString::fromUtf8(text[language]);
    if(language==2)value.replace(QStringLiteral("Запустить Sound Doctor"),QStringLiteral("Запустить Консультанта по звуку")).replace(QStringLiteral("Перед запуском Sound Doctor"),QStringLiteral("Перед запуском Консультанта по звуку")).replace(QStringLiteral("Рекомендации Sound Doctor"),QStringLiteral("Рекомендации Консультанта по звуку")).replace(QStringLiteral("Sound Doctor – Compressor"),QStringLiteral("Консультант по звуку – Компрессор")).replace(QStringLiteral("Sound Doctor – Limiter"),QStringLiteral("Консультант по звуку – Лимитер")).replace(QStringLiteral("Sound Doctor"),QStringLiteral("Консультант по звуку")).replace(QStringLiteral("Audible Meter"),QStringLiteral("Звуковой индикатор"));
    else if(language==3)value.replace(QStringLiteral("Запустити Sound Doctor"),QStringLiteral("Запустити Консультанта зі звуку")).replace(QStringLiteral("Перед запуском Sound Doctor"),QStringLiteral("Перед запуском Консультанта зі звуку")).replace(QStringLiteral("Рекомендації Sound Doctor"),QStringLiteral("Рекомендації Консультанта зі звуку")).replace(QStringLiteral("Sound Doctor – Compressor"),QStringLiteral("Консультант зі звуку – Компресор")).replace(QStringLiteral("Sound Doctor – Limiter"),QStringLiteral("Консультант зі звуку – Лімітер")).replace(QStringLiteral("Sound Doctor"),QStringLiteral("Консультант зі звуку")).replace(QStringLiteral("Audible Meter"),QStringLiteral("Звуковий індикатор"));
    return value;
}

