static int Bin(double db){return std::clamp(static_cast<int>(std::lround(db))-MIN_DB,0,BINS-1);}
static double Percentile(const std::array<uint64_t,BINS> &bins,double fraction){
    uint64_t total=0;for(uint64_t count:bins)total+=count;if(!total)return -INFINITY;
    uint64_t target=std::max<uint64_t>(1,static_cast<uint64_t>(std::ceil(total*fraction))),sum=0;
    for(int i=0;i<BINS;++i){sum+=bins[static_cast<size_t>(i)];if(sum>=target)return i+MIN_DB;}return MAX_DB;
}
static bool MicrophoneType(const QString &type){return type==QStringLiteral("wasapi_input_capture")||type==QStringLiteral("dshow_input");}

static void EnumFilter(void*,void *filter,void *parameter){
    auto *items=static_cast<std::vector<FilterInfo>*>(parameter);QString type=QString::fromUtf8(api.source_id(filter)?api.source_id(filter):""),name=QString::fromUtf8(api.source_name(filter)?api.source_name(filter):"");
    obs_data *settings=api.source_settings(filter);bool managed=settings&&api.data_get_bool(settings,"sound_doctor_managed");QByteArray json;double threshold=0,ratio=0,outputGain=0;long long attack=0,release=0;if(settings){const char *raw=api.data_json(settings);if(raw)json=raw;threshold=api.data_get_double(settings,"threshold");ratio=api.data_get_double(settings,"ratio");outputGain=api.data_get_double(settings,"output_gain");attack=api.data_get_int(settings,"attack_time");release=api.data_get_int(settings,"release_time");api.data_release(settings);}
    QString fingerprint=QString::fromLatin1(QCryptographicHash::hash(json,QCryptographicHash::Sha256).toHex());items->push_back({name,type,fingerprint,api.source_enabled(filter),managed,threshold,ratio,outputGain,attack,release});
}
static std::vector<FilterInfo> Filters(void *source){std::vector<FilterInfo> result;if(source)api.enum_filters(source,EnumFilter,&result);return result;}
static QString FilterFingerprint(void *source){
    QJsonArray values;for(const FilterInfo &filter:Filters(source))values.append(QJsonObject{{"name",filter.name},{"type",filter.type},{"settings",filter.settingsFingerprint},{"enabled",filter.enabled},{"managed",filter.managed}});
    return QString::fromLatin1(QCryptographicHash::hash(QJsonDocument(values).toJson(QJsonDocument::Compact),QCryptographicHash::Sha256).toHex());
}
static void Meter(void *parameter,const float *magnitude,const float *peak,const float *inputPeak){
    auto *source=static_cast<Source*>(parameter);if(!source||!running.load()||!magnitude||!peak||!inputPeak)return;
    double rms=-INFINITY,peakDb=-INFINITY,input=-INFINITY;for(int i=0;i<std::clamp(source->channels,1,MAX_CHANNELS);++i){if(std::isfinite(magnitude[i]))rms=std::max(rms,double(magnitude[i]));if(std::isfinite(peak[i]))peakDb=std::max(peakDb,double(peak[i]));if(std::isfinite(inputPeak[i]))input=std::max(input,double(inputPeak[i]));}
    auto now=std::chrono::steady_clock::now();std::unique_lock<std::mutex> lock(source->mutex,std::try_to_lock);if(!lock.owns_lock()||!running.load())return;
    double delta=source->lastCallback.time_since_epoch().count()?std::chrono::duration<double,std::milli>(now-source->lastCallback).count():0;source->lastCallback=now;delta=std::clamp(delta,0.0,100.0);
    float volume=source->source?api.source_get_volume(source->source):source->initialVolume;if(std::abs(volume-source->initialVolume)>std::max(0.001f,std::abs(source->initialVolume)*0.01f))source->levelChanged=true;
    if(std::isfinite(rms)&&rms>=-60.0){source->activeMs+=delta;++source->rmsBins[static_cast<size_t>(Bin(rms))];if(std::isfinite(peakDb)){++source->peakBins[static_cast<size_t>(Bin(peakDb))];source->maxPeak=std::max(source->maxPeak,peakDb);if(peakDb>=-3.0&&!source->highPeak){++source->peakEvents;source->highPeak=true;}}}if(!std::isfinite(peakDb)||peakDb<-6.0)source->highPeak=false;
    if(std::isfinite(input)){if(input>=-1.0&&!source->inputClipping){++source->inputClipEvents;source->inputClipping=true;}else if(input<-4.0)source->inputClipping=false;}
}
static void Detach(Source &source){if(source.meter){api.volmeter_remove_callback(source.meter,Meter,&source);api.volmeter_detach(source.meter);api.volmeter_destroy(source.meter);source.meter=nullptr;}if(source.source){api.source_release(source.source);source.source=nullptr;}}
static bool Attach(Source &source,void *enumerated){
    void *reference=api.source_get_ref(enumerated);if(!reference)return false;obs_volmeter *meter=api.volmeter_create(FADER_LOG);if(!meter){api.source_release(reference);return false;}api.volmeter_set_peak_type(meter,CurrentPeakType());api.volmeter_add_callback(meter,Meter,&source);
    if(!api.volmeter_attach(meter,reference)){api.volmeter_remove_callback(meter,Meter,&source);api.volmeter_destroy(meter);api.source_release(reference);return false;}
    float volume=api.source_get_volume(reference);QString fingerprint=FilterFingerprint(reference);if(source.initialFilterFingerprint.isEmpty()){source.initialVolume=volume;source.initialFilterFingerprint=fingerprint;}else if(std::abs(volume-source.initialVolume)>std::max(0.001f,std::abs(source.initialVolume)*0.01f)||fingerprint!=source.initialFilterFingerprint)source.levelChanged=true;
    source.source=reference;source.meter=meter;source.channels=std::clamp(api.volmeter_channels(meter),1,MAX_CHANNELS);return true;
}
static bool Collect(void *parameter,void *enumerated){
    auto *active=static_cast<std::vector<QString>*>(parameter);if(!enumerated||(api.source_output_flags(enumerated)&AUDIO_FLAG)==0||!api.source_active(enumerated)||!api.source_audio_active(enumerated))return true;
    QString uuid=QString::fromUtf8(api.source_uuid(enumerated)?api.source_uuid(enumerated):"");if(uuid.isEmpty())return true;active->push_back(uuid);
    auto found=std::find_if(sources.begin(),sources.end(),[&](const auto &source){return source->uuid==uuid;});if(found==sources.end()){auto source=std::make_unique<Source>();source->uuid=uuid;source->name=QString::fromUtf8(api.source_name(enumerated)?api.source_name(enumerated):"Audio source");source->type=QString::fromUtf8(api.source_id(enumerated)?api.source_id(enumerated):"");if(Attach(*source,enumerated))sources.push_back(std::move(source));}else if(!(*found)->meter)Attach(*(*found),enumerated);
    return true;
}
static void Refresh(){
    if(!running.load())return;std::vector<QString> active;api.enum_sources(Collect,&active);
    for(auto &source:sources)if(source->meter&&std::find(active.begin(),active.end(),source->uuid)==active.end())Detach(*source);
}
struct Lookup{QString uuid;void *source{};};
static bool Find(void *parameter,void *enumerated){auto *lookup=static_cast<Lookup*>(parameter);QString uuid=QString::fromUtf8(api.source_uuid(enumerated)?api.source_uuid(enumerated):"");if(uuid!=lookup->uuid)return true;lookup->source=api.source_get_ref(enumerated);return false;}

static void Analyze(){
    recommendations.clear();observations.clear();int nextId=1;constexpr double minimumActiveMs=DEFAULT_MIN_ACTIVE_SECONDS*1000.0;double minimumSpread=MinimumCompressionSpreadDb(),maximumRatio=MaximumCompressionRatio(),limiterThreshold=LimiterThresholdDb();bool limiterAllSources=LimiterAllActiveSources();
    for(auto &source:sources){
        std::lock_guard<std::mutex> lock(source->mutex);Lookup lookup{source->uuid};api.enum_sources(Find,&lookup);void *current=lookup.source;QString currentFingerprint=current?FilterFingerprint(current):QString{};QStringList notes;
        std::vector<FilterInfo> filters=current?Filters(current):std::vector<FilterInfo>{};bool compressor=false,limiter=false;
        for(size_t index=0;index<filters.size();++index){const FilterInfo &filter=filters[index];QString state=T(filter.enabled?ENABLED:DISABLED);if(filter.type==QStringLiteral("compressor_filter")){compressor=true;notes.push_back(T(COMPRESSOR_DETAILS).arg(filter.name,state).arg(filter.threshold,0,'f',1).arg(filter.ratio,0,'f',1).arg(filter.attack).arg(filter.release).arg(filter.outputGain,0,'f',1));}if(filter.type==QStringLiteral("limiter_filter")){limiter=true;notes.push_back(T(LIMITER_DETAILS).arg(filter.name,state).arg(filter.threshold,0,'f',1).arg(filter.release));if(index+1<filters.size())notes.push_back(T(LIMITER_NOT_LAST));}}
        if(source->activeMs<minimumActiveMs)notes.push_back(T(INSUFFICIENT).arg(source->name).arg(std::lround(source->activeMs/1000.0)));if(compressor)notes.push_back(T(EXISTING_COMPRESSOR));if(limiter)notes.push_back(T(EXISTING_LIMITER));
        bool changed=source->levelChanged||!current||currentFingerprint!=source->initialFilterFingerprint;if(changed)notes.push_back(T(CHANGED_DURING_TEST));
        if(source->inputClipEvents>=3)notes.push_back(T(PREFADER_CLIPPING).arg(source->name).arg(source->inputClipEvents));
        if(!notes.isEmpty())observations.push_back(QStringLiteral("%1: %2").arg(source->name,notes.join(QLatin1Char(' '))));
        if(source->activeMs>=minimumActiveMs&&!changed){
            double median=Percentile(source->rmsBins,0.50),loud=Percentile(source->rmsBins,0.95),spread=loud-median;
            if(MicrophoneType(source->type)&&!compressor&&spread>=minimumSpread){
                double threshold=std::clamp(std::round(std::max(-24.0,median+5.0)),-24.0,-10.0),ratio=spread>=14.0?maximumRatio:spread>=10.0?std::min(2.5,maximumRatio):2.0;
                Recommendation item;item.id=QString::number(nextId++);item.uuid=source->uuid;item.sourceName=source->name;item.expectedFilterFingerprint=currentFingerprint;item.kind=Kind::Compressor;item.threshold=threshold;item.ratio=ratio;item.expectedVolume=current?api.source_get_volume(current):source->initialVolume;item.reason=T(COMPRESSOR_REASON).arg(spread,0,'f',0);item.settings=T(COMPRESSOR_SETTINGS).arg(threshold,0,'f',0).arg(ratio,0,'f',1);recommendations.push_back(std::move(item));
            }
            if((limiterAllSources||MicrophoneType(source->type))&&!limiter){
                Recommendation item;item.id=QString::number(nextId++);item.uuid=source->uuid;item.sourceName=source->name;item.expectedFilterFingerprint=currentFingerprint;item.kind=Kind::Limiter;item.threshold=limiterThreshold;item.expectedVolume=current?api.source_get_volume(current):source->initialVolume;item.reason=T(LIMITER_REASON);item.settings=T(LIMITER_SETTINGS).arg(limiterThreshold,0,'f',1);recommendations.push_back(std::move(item));
            }
        }
        if(current)api.source_release(current);
    }
}

static QString UniqueFilterName(void *source,const QString &base){
    for(int suffix=1;suffix<100;++suffix){QString candidate=suffix==1?base:QStringLiteral("%1 %2").arg(base).arg(suffix);QByteArray name=candidate.toUtf8();void *existing=api.source_filter_by_name(source,name.constData());if(!existing)return candidate;api.source_release(existing);}return {};
}
static bool HasFilter(void *source,const QString &type){for(const FilterInfo &filter:Filters(source))if(filter.type==type)return true;return false;}
static bool AddFilter(const Recommendation &item,QString *createdName=nullptr){
    Lookup lookup{item.uuid};api.enum_sources(Find,&lookup);if(!lookup.source)return false;QString type=item.kind==Kind::Compressor?QStringLiteral("compressor_filter"):QStringLiteral("limiter_filter");
    float currentVolume=api.source_get_volume(lookup.source);float tolerance=std::max(0.001f,std::abs(item.expectedVolume)*0.01f);if(!item.expectedFilterFingerprint.isEmpty()&&(FilterFingerprint(lookup.source)!=item.expectedFilterFingerprint||std::abs(currentVolume-item.expectedVolume)>tolerance)){api.source_release(lookup.source);return false;}if(HasFilter(lookup.source,type)){api.source_release(lookup.source);return false;}
    QString base=item.kind==Kind::Compressor?T(COMPRESSOR_NAME):T(LIMITER_NAME),name=UniqueFilterName(lookup.source,base);if(name.isEmpty()){api.source_release(lookup.source);return false;}
    obs_data *settings=api.data_create();api.data_set_bool(settings,"sound_doctor_managed",true);api.data_set_int(settings,"sound_doctor_schema",1);api.data_set_string(settings,"sound_doctor_kind",item.kind==Kind::Compressor?"compressor":"limiter");api.data_set_double(settings,"threshold",item.threshold);
    if(item.kind==Kind::Compressor){api.data_set_double(settings,"ratio",item.ratio);api.data_set_int(settings,"attack_time",6);api.data_set_int(settings,"release_time",100);api.data_set_double(settings,"output_gain",0.0);api.data_set_string(settings,"sidechain_source","none");}else api.data_set_int(settings,"release_time",60);
    QByteArray typeUtf8=type.toUtf8(),nameUtf8=name.toUtf8();void *filter=api.source_create(typeUtf8.constData(),nameUtf8.constData(),settings,nullptr);api.data_release(settings);if(!filter){api.source_release(lookup.source);return false;}api.source_filter_add(lookup.source,filter);api.source_filter_set_order(lookup.source,filter,item.kind==Kind::Compressor?2:3);api.source_release(filter);api.source_release(lookup.source);if(createdName)*createdName=name;return true;
}
static void RemoveApplied(const char *raw){
    QJsonDocument document=QJsonDocument::fromJson(QByteArray(raw?raw:""));if(!document.isArray())return;for(const QJsonValue &value:document.array()){QJsonObject object=value.toObject();Lookup lookup{object.value("uuid").toString()};api.enum_sources(Find,&lookup);if(!lookup.source)continue;QByteArray name=object.value("name").toString().toUtf8();void *filter=api.source_filter_by_name(lookup.source,name.constData());if(filter){obs_data *settings=api.source_settings(filter);bool managed=settings&&api.data_get_bool(settings,"sound_doctor_managed");if(settings)api.data_release(settings);if(managed)api.source_filter_remove(lookup.source,filter);api.source_release(filter);}api.source_release(lookup.source);}if(api.frontend_save)api.frontend_save();
}
static void RedoApplied(const char *raw){
    QJsonDocument document=QJsonDocument::fromJson(QByteArray(raw?raw:""));if(!document.isArray())return;for(const QJsonValue &value:document.array()){QJsonObject object=value.toObject();Recommendation item;item.uuid=object.value("uuid").toString();item.kind=object.value("kind").toString()=="compressor"?Kind::Compressor:Kind::Limiter;item.threshold=object.value("threshold").toDouble();item.ratio=object.value("ratio").toDouble();AddFilter(item);}if(api.frontend_save)api.frontend_save();
}
static void ApplySelected(const QStringList &ids){
    QJsonArray undoData,redoData;int applied=0,skipped=0;
    for(const QString &id:ids){auto found=std::find_if(recommendations.begin(),recommendations.end(),[&](const Recommendation &item){return item.id==id;});if(found==recommendations.end()){++skipped;continue;}QString created;if(!AddFilter(*found,&created)){++skipped;continue;}++applied;undoData.append(QJsonObject{{"uuid",found->uuid},{"name",created}});redoData.append(QJsonObject{{"uuid",found->uuid},{"kind",found->kind==Kind::Compressor?"compressor":"limiter"},{"threshold",found->threshold},{"ratio",found->ratio}});Lookup updated{found->uuid};api.enum_sources(Find,&updated);if(updated.source){QString fingerprint=FilterFingerprint(updated.source);float volume=api.source_get_volume(updated.source);for(Recommendation &candidate:recommendations)if(candidate.uuid==found->uuid){candidate.expectedFilterFingerprint=fingerprint;candidate.expectedVolume=volume;}api.source_release(updated.source);}}
    if(applied){if(api.frontend_save)api.frontend_save();if(api.add_undo_redo){QByteArray undo=QJsonDocument(undoData).toJson(QJsonDocument::Compact),redo=QJsonDocument(redoData).toJson(QJsonDocument::Compact),label=T(APPLY_UNDO).toUtf8();api.add_undo_redo(label.constData(),RemoveApplied,RedoApplied,undo.constData(),redo.constData(),false);}}
    QString message=T(APPLY_SUMMARY).arg(applied);if(skipped)message+=QLatin1Char(' ')+T(APPLY_PARTIAL).arg(skipped);QMessageBox::information(obsMainWindow,T(TITLE),message);
}

